def do_algebra(operator, operand):
    if not operator or not operand:
        raise ValueError("Both operator and operand lists must be provided.")

    if len(operator) != len(operand) - 1:
        raise ValueError("The length of operator list is not equal to the length of operand list minus one.")

    if not all(isinstance(x, int) and x >= 0 for x in operand):
        raise ValueError("Operand list must contain only non-negative integers.")

    result = operand[0]
    for i in range(len(operator)):
        if operator[i] == '+':
            result += operand[i + 1]
        elif operator[i] == '-':
            result -= operand[i + 1]
        elif operator[i] == '*':
            result *= operand[i + 1]
        elif operator[i] == '//':
            result //= operand[i + 1]
        elif operator[i] == '**':
            result **= operand[i + 1]

    return result
