def solve(s):
    # Check if the string contains any letters
    has_letters = any(char.isalpha() for char in s)

    # If no letters, reverse the string
    if not has_letters:
        return s[::-1]

    # Otherwise, reverse the case of letters
    result = []
    for char in s:
        if char.isalpha():
            result.append(char.swapcase())
        else:
            result.append(char)

    return ''.join(result)
